const out = [];
for (const item of $input.all()) {
  const d = item.json || {};
  const statusCandidates = [
    d.statusCode, d.status, d.httpStatus,
    d.error?.statusCode, d.error?.httpCode,
    d.error?.response?.statusCode, d.error?.response?.status,
    d.error?.cause?.statusCode
  ];
  const http_status = statusCandidates.find(v => Number.isFinite(Number(v))) != null
    ? Number(statusCandidates.find(v => Number.isFinite(Number(v)))) : null;
  const messageId = d.messages?.[0]?.id ?? d.message_id ?? d.id ?? null;

  const accepted = Array.isArray(d.messages) && d.messages.length > 0 && !d.error && (http_status === null || (http_status >= 200 && http_status < 300));

  const is_explicit_retryable = http_status === 408 || http_status === 425 || http_status === 429 || (http_status >= 500 && http_status <= 599);
  const unknown = !accepted && (http_status === null);
  const retryable = !accepted && !unknown && is_explicit_retryable;
  const permanent = !accepted && !unknown && !retryable;

  out.push({json:{
    ...d,
    http_status,
    whatsapp_message_id: messageId,
    whatsapp_accepted: accepted,
    retryable,
    unknown,
    permanent,
    api_error_code: d.error?.code ?? d.code ?? null,
    error_message: String(d.error?.message ?? d.message ?? '').slice(0,1000)
  }});
}
return out;

