WITH updated AS (
  UPDATE reminder_log SET last_error='IN_FLIGHT', updated_at=now() 
  WHERE id=$1::uuid AND locked_at=$2::timestamptz AND status='PENDING' 
  RETURNING id
)
SELECT COALESCE((SELECT 'SUCCESS' FROM updated), 'CLAIM_LOST') AS in_flight_result;
